def gen_rating():
    r = RNG.random()
    if r < 0.18:
        base = RNG.uniform(3.4, 3.9)
    elif r < 0.55:
        base = RNG.uniform(3.9, 4.3)
    elif r < 0.88:
        base = RNG.uniform(4.3, 4.6)
    else:
        base = RNG.uniform(4.6, 4.9)
    return round(base * 2) / 2.0


